@theme {
  --breakpoint-sm: 33.75rem;
  --breakpoint-md: 36.25rem;

  --font-sans: "Lora", ui-sans-serif, system-ui, sans-serif;
  --font-serif: "Cinzel", ui-serif, Georgia, serif;
  --font-arabic: "Amiri", serif;
  --font-urdu: "Noto Nastaliq Urdu", serif;
  --font-hindi: "Amita", "Noto Sans Devanagari", sans-serif;


  --color-brand-black: #050505;
  --color-brand-dark: #0a0a0a;
  --color-brand-gray: #1a1a1a;
  --color-brand-gold-light: #FBE7A1;
  --color-brand-gold: #D4AF37;
  --color-brand-gold-dark: #A67C00;
  --color-brand-crimson: #8B0000;
  --color-brand-crimson-dark: #5c0000;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}

body {
  @apply bg-brand-black text-gray-200 font-sans;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  @apply bg-brand-black;
}
::-webkit-scrollbar-thumb {
  @apply bg-brand-gold-dark/50 rounded-full;
}
::-webkit-scrollbar-thumb:hover {
  @apply bg-brand-gold;
}

